# frozen_string_literal: true

module Feedbacks
  # Adds the active locale to notification links generated by Noticed.
  module NotificationsHelper
    def localized_notification_url(url)
      return url if url.blank?

      parsed_url = URI.parse(url)
      parsed_url.path = localized_notification_path(parsed_url.path)
      parsed_url.to_s
    end

    private

    def localized_notification_path(path)
      segments = path.split('/')
      locale = I18n.locale.to_s

      if I18n.available_locales.map(&:to_s).include?(segments[1])
        segments[1] = locale
      else
        segments.insert(1, locale)
      end

      segments.join('/')
    end
  end
end
